RegisteredWidget:
/**
 * A widget as it lives in the registry — definition plus its React
 * component. The non-React `RegisteredWidgetBase` lives in core’s schema layer
 * so validators don’t pull React types.
 */
export interface RegisteredWidget<Kind extends string = string, PayloadSchema extends AnyValibotSchema = AnyValibotSchema, Actions extends Record<string, AnyValibotSchema> = Record<string, AnyValibotSchema>> extends WidgetDef<Kind, PayloadSchema, Actions> {
    readonly component: ComponentType<CanvasWidgetProps>;
}
